// vehiculos.js — SVGs reales de inspección vehicular
// Cargado externamente para no modificar index.html

const FL_VEHICLE_VIEWS = {
  car: {
    front: { vb: '0 0 302.96 219.97', html: `<image width="303" height="220" xlink:href="data:image/png;base64,"/>` },
    back:  { vb: '0 0 302.96 221.97', html: `<image width="303" height="222" xlink:href="data:image/png;base64,"/>` },
    left:  { vb: '0 0 657.92 215.97', html: `<image width="658" height="216" xlink:href="data:image/png;base64,"/>` },
    right: { vb: '0 0 656.92 215.97', html: `<image width="657" height="216" xlink:href="data:image/png;base64,"/>` }
  },
  truck: {
    front: { vb: '0 0 283.96 253.97', html: `<image width="284" height="254" xlink:href="data:image/png;base64,"/>` },
    back:  { vb: '0 0 290.96 256.97', html: `<image width="291" height="257" xlink:href="data:image/png;base64,"/>` },
    left:  { vb: '0 0 685.91 245.97', html: `<image width="686" height="246" xlink:href="data:image/png;base64,"/>` },
    right: { vb: '0 0 684.91 235.97', html: `<image width="685" height="236" xlink:href="data:image/png;base64,"/>` }
  }
};

function flMakeSVGView(type, viewKey, label){
  const v = FL_VEHICLE_VIEWS[type][viewKey];
  const vbParts = v.vb.split(' ');
  const w = vbParts[2], h = vbParts[3];
  return `<div style="position:relative;">
    <div style="font-size:8px;font-weight:800;color:#94a3b8;text-align:center;margin-bottom:3px;text-transform:uppercase;letter-spacing:.06em;">${label}</div>
    <svg viewBox="${v.vb}" xmlns="http://www.w3.org/2000/svg" style="width:100%;background:#f8fafc;border-radius:8px;border:1.5px solid #e2e8f0;cursor:crosshair;" data-view="${viewKey}">${v.html}<rect x="0" y="0" width="100%" height="100%" fill="transparent" onclick="flAddDamage(event,'${viewKey}')"/></svg>
  </div>`;
}

function flRenderVehicleViews(type){
  return `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;width:100%;" id="fl-car-views">
    ${flMakeSVGView(type,'front','FRENTE')}
    ${flMakeSVGView(type,'back','TRASERA')}
    ${flMakeSVGView(type,'left','LATERAL IZQ.')}
    ${flMakeSVGView(type,'right','LATERAL DER.')}
  </div>`;
}

function flSwitchVehicle(type){
  window._flVehicleType = type;
  const container = document.getElementById('fl-vehicle-views');
  if(container){
    container.innerHTML = flRenderVehicleViews(type);
    if(window._flDamagePoints){
      Object.entries(window._flDamagePoints).forEach(([view,points])=>{
        points.forEach(p=>{
          const svg = container.querySelector(`[data-view="${view}"]`);
          if(svg) flRenderDot(svg, p.x, p.y, p.n);
        });
      });
    }
  }
  const btnCar   = document.getElementById('fl-btn-car');
  const btnTruck = document.getElementById('fl-btn-truck');
  if(btnCar && btnTruck){
    if(type==='car'){
      btnCar.style.cssText  ='flex:1;padding:8px 0;border-radius:8px;border:2px solid #3b82f6;background:#eff6ff;color:#1d4ed8;font-weight:700;font-size:13px;cursor:pointer;';
      btnTruck.style.cssText='flex:1;padding:8px 0;border-radius:8px;border:2px solid #e2e8f0;background:#f8fafc;color:#64748b;font-weight:700;font-size:13px;cursor:pointer;';
    }else{
      btnTruck.style.cssText='flex:1;padding:8px 0;border-radius:8px;border:2px solid #3b82f6;background:#eff6ff;color:#1d4ed8;font-weight:700;font-size:13px;cursor:pointer;';
      btnCar.style.cssText  ='flex:1;padding:8px 0;border-radius:8px;border:2px solid #e2e8f0;background:#f8fafc;color:#64748b;font-weight:700;font-size:13px;cursor:pointer;';
    }
  }
}
